solution.solution.c:
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct entry { char *key; int value; struct entry *next; };
struct table { struct entry **buckets; size_t bucket_count; size_t size; };

static uint32_t hash(const char *key)
{
    uint32_t h = 2166136261u;
    for (const unsigned char *p = (const unsigned char *)key; *p; p++) {
        h ^= *p;
        h *= 16777619u;
    }
    return h;
}

bool table_init(struct table *t, size_t bucket_count)
{
    if (bucket_count == 0) bucket_count = 1;
    t->buckets = calloc(bucket_count, sizeof *t->buckets);
    if (t->buckets == NULL) return false;
    t->bucket_count = bucket_count;
    t->size = 0;
    return true;
}

static struct entry *find(const struct table *t, const char *key)
{
    for (struct entry *e = t->buckets[hash(key) % t->bucket_count]; e != NULL; e = e->next) {
        if (strcmp(e->key, key) == 0) return e;
    }
    return NULL;
}

static bool grow(struct table *t)
{
    size_t new_count = t->bucket_count * 2;
    struct entry **fresh = calloc(new_count, sizeof *fresh);
    if (fresh == NULL) return false;
    for (size_t i = 0; i < t->bucket_count; i++) {
        struct entry *e = t->buckets[i];
        while (e != NULL) {
            struct entry *next = e->next;
            size_t b = hash(e->key) % new_count;
            e->next = fresh[b];
            fresh[b] = e;
            e = next;
        }
    }
    free(t->buckets);
    t->buckets = fresh;
    t->bucket_count = new_count;
    return true;
}

bool table_put(struct table *t, const char *key, int value)
{
    struct entry *found = find(t, key);
    if (found != NULL) {
        found->value = value;
        return true;
    }
    struct entry *e = malloc(sizeof *e);
    if (e == NULL) return false;
    size_t length = strlen(key) + 1;
    e->key = malloc(length);
    if (e->key == NULL) {
        free(e);
        return false;
    }
    memcpy(e->key, key, length);
    e->value = value;
    size_t b = hash(key) % t->bucket_count;
    e->next = t->buckets[b];
    t->buckets[b] = e;
    t->size++;
    if (t->size > t->bucket_count) grow(t);
    return true;
}

bool table_get(const struct table *t, const char *key, int *value)
{
    struct entry *e = find(t, key);
    if (e == NULL) return false;
    *value = e->value;
    return true;
}

bool table_remove(struct table *t, const char *key)
{
    struct entry **link = &t->buckets[hash(key) % t->bucket_count];
    for (; *link != NULL; link = &(*link)->next) {
        if (strcmp((*link)->key, key) == 0) {
            struct entry *gone = *link;
            *link = gone->next;
            free(gone->key);
            free(gone);
            t->size--;
            return true;
        }
    }
    return false;
}

void table_free(struct table *t)
{
    for (size_t i = 0; i < t->bucket_count; i++) {
        struct entry *e = t->buckets[i];
        while (e != NULL) {
            struct entry *next = e->next;
            free(e->key);
            free(e);
            e = next;
        }
    }
    free(t->buckets);
    t->buckets = NULL;
    t->bucket_count = 0;
    t->size = 0;
}

unitTests:
TEST("put and get") { struct table t; CHECK(table_init(&t, 8)); int v = 0; CHECK(!table_get(&t, "cat", &v)); CHECK(table_put(&t, "cat", 3)); CHECK(table_put(&t, "dog", 5)); CHECK(table_get(&t, "cat", &v)); CHECK_EQ(v, 3); CHECK(table_get(&t, "dog", &v)); CHECK_EQ(v, 5); CHECK_EQ(t.size, (size_t)2); table_free(&t); }
TEST("updating a key") { struct table t; table_init(&t, 8); table_put(&t, "cat", 3); table_put(&t, "cat", 30); int v = 0; CHECK(table_get(&t, "cat", &v)); CHECK_EQ(v, 30); CHECK_EQ(t.size, (size_t)1); table_free(&t); }
TEST("the table keeps its own copy of keys") { struct table t; table_init(&t, 8); char buffer[16] = "first"; table_put(&t, buffer, 1); snprintf(buffer, sizeof buffer, "second"); table_put(&t, buffer, 2); int v = 0; CHECK(table_get(&t, "first", &v)); CHECK_EQ(v, 1); CHECK(table_get(&t, "second", &v)); CHECK_EQ(v, 2); table_free(&t); }
TEST("removing") { struct table t; table_init(&t, 4); table_put(&t, "a", 1); table_put(&t, "b", 2); table_put(&t, "c", 3); CHECK(table_remove(&t, "b")); CHECK(!table_remove(&t, "b")); int v = 0; CHECK(!table_get(&t, "b", &v)); CHECK(table_get(&t, "a", &v)); CHECK(table_get(&t, "c", &v)); CHECK_EQ(t.size, (size_t)2); table_free(&t); }
TEST("collisions in one bucket") { struct table t; table_init(&t, 1); table_put(&t, "x", 1); CHECK_EQ(t.bucket_count, (size_t)1); table_put(&t, "y", 2); int v = 0; CHECK(table_get(&t, "x", &v)); CHECK_EQ(v, 1); CHECK(table_get(&t, "y", &v)); CHECK_EQ(v, 2); table_free(&t); }
TEST("growing") { struct table t; table_init(&t, 4); char key[16]; for (int i = 0; i < 1000; i++) { snprintf(key, sizeof key, "key%d", i); table_put(&t, key, i * i); } CHECK_EQ(t.size, (size_t)1000); CHECK_EQ(t.bucket_count, (size_t)1024); int v = 0; int all = 1; for (int i = 0; i < 1000; i++) { snprintf(key, sizeof key, "key%d", i); if (!table_get(&t, key, &v) || v != i * i) all = 0; } CHECK(all); CHECK(!table_get(&t, "key1000", &v)); table_free(&t); CHECK_EQ(t.size, (size_t)0); CHECK(t.buckets == NULL); }

